{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#0f1720;--muted:#98a0a6;--accent:#8ec5ff;--card:#0b1220;--glass:rgba(255,255,255,0.04)}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#e6eef6;background:linear-gradient(180deg,#071021 0%,#081226 40%),url('assets/img/pattern.svg');background-size:600px 600px}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter:blur(6px)}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#6bd6a6);display:flex;align-items:center;justify-content:center;font-weight:700;color:#04202a}
    nav a{color:var(--muted);text-decoration:none;margin:0 10px;font-size:15px}
    nav a.active{color:#fff}
    .container{max-width:1100px;margin:28px auto;padding:20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:24px;align-items:start}
    .hero-card{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:28px;border-radius:12px;box-shadow:0 6px 30px rgba(2,8,23,0.6)}
    h1{margin:0 0 12px 0;font-size:28px;color:#fff}
    p.lead{color:var(--muted);margin:0 0 18px 0;line-height:1.5}
    .pillars{display:flex;gap:12px;margin-top:12px}
    .pillar{flex:1;background:var(--glass);padding:14px;border-radius:10px;color:var(--muted)}
    .proof{margin-top:18px}
    .proof-rotator{position:relative;height:140px;overflow:hidden;border-radius:10px}
    .testimonial{position:absolute;inset:0;padding:18px;display:flex;flex-direction:column;justify-content:center;transition:transform .6s cubic-bezier(.2,.9,.2,1),opacity .4s}
    .testimonial p{margin:0;color:#e8f3ff}
    .meta{margin-top:10px;display:flex;align-items:center;gap:10px}
    .badge{background:#071a26;padding:6px 8px;border-radius:6px;font-size:12px;color:var(--muted);cursor:help}
    .badges{display:flex;gap:10px;margin-top:10px}
    .case-notes{margin-top:18px;background:linear-gradient(180deg,rgba(255,255,255,0.01),transparent);padding:16px;border-radius:10px;color:var(--muted)}
    .disclaimer{margin-top:12px;font-size:13px;color:#ffd6d6;background:linear-gradient(90deg,rgba(255,200,200,0.02),transparent);padding:12px;border-radius:8px}
    .cta{display:inline-block;margin-top:16px;padding:12px 18px;border-radius:9px;background:linear-gradient(90deg,var(--accent),#5ad2b9);color:#04202a;text-decoration:none;font-weight:600}
    footer{margin-top:40px;padding:18px;color:var(--muted);font-size:14px;text-align:center}
    /* tooltip */
    .tooltip{position:absolute;background:#02111a;color:#bfe9ff;padding:8px;border-radius:6px;font-size:13px;transform:translateY(-6px);white-space:nowrap;box-shadow:0 6px 20px rgba(2,8,23,0.6);opacity:0;pointer-events:none;transition:opacity .18s}
    .badge:hover + .tooltip, .badge:focus + .tooltip{opacity:1}
    /* small responsive */
    @media(max-width:860px){.hero{grid-template-columns:1fr;}.brand h2{display:none}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700;color:#dff6ff">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private Care</a>
      <a href="pricing.html">Memberships</a>
      <a href="about.html" class="active">About</a>
      <a href="faq.html">Questions</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div class="hero-card">
        <h1>Sound as a map: steady practices and short resets</h1>
        <p class="lead">We design shared sound experiences and private sessions that help you notice bodily rhythms, lower arousal, and cultivate a clearer sense of rest. Gentle instruments, subtle envelopes of tone, and guided pauses make space for everyday recovery.</p>

        <div class="pillars">
          <div class="pillar"><strong>Rituals</strong>
            <div style="font-size:13px;margin-top:8px">Recurring group evenings that anchor into a monthly cadence.</div>
          </div>
          <div class="pillar"><strong>Care</strong>
            <div style="font-size:13px;margin-top:8px">Private sessions tailored to pace and medical considerations.</div>
          </div>
          <div class="pillar"><strong>Accessibility</strong>
            <div style="font-size:13px;margin-top:8px">Lower-volume options, seating variety, and visual cueing for navigation.</div>
          </div>
        </div>

        <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>

        <div class="case-notes">
          <strong>How we think about progress</strong>
          <p style="margin-top:8px">Sound isn’t a magic switch. We combine paced listening, brief breath frameworks, and guided reflection to help you notice small shifts over multiple sessions.</p>
        </div>

        <div class="disclaimer">
          <strong>Important contraindications</strong>
          <p style="margin-top:6px">If you are pregnant, have epilepsy, a pacemaker or other implanted device, are on photosensitizing medication, or have seizure history, please consult your medical provider before attending. Inform us ahead of private sessions to adapt tone and posture.</p>
        </div>
      </div>

      <aside class="hero-card">
        <div style="font-weight:700;color:#dff6ff">A short portrait</div>
        <p style="color:var(--muted);margin-top:8px">Sessions last 45–75 minutes. We favor smaller groups and intention-led openings. Memberships provide priority booking and lower per-session cost.</p>

        <div class="proof">
          <div style="font-weight:700;color:#cfeeff;margin-bottom:8px">Proof Gallery</div>
          <div class="proof-rotator" id="rotator">
            <!-- testimonials injected by JS -->
          </div>

          <div class="badges" style="margin-top:12px">
            <div style="position:relative">
              <div class="badge" tabindex="0" data-tip="Listed on the local wellbeing guide">Local Guide</div>
              <div class="tooltip">Awarded to small community practitioners — vetted inclusion.</div>
            </div>
            <div style="position:relative">
              <div class="badge" tabindex="0" data-tip="Independent safety review">Safety Reviewed</div>
              <div class="tooltip">Independent review of session safety and contraindications.</div>
            </div>
            <div style="position:relative">
              <div class="badge" tabindex="0" data-tip="Membership satisfaction metric">Member Rated</div>
              <div class="tooltip">Consistent 4.8+ satisfaction among renewing members.</div>
            </div>
          </div>
        </div>
      </aside>
    </section>

    <section style="margin-top:28px" class="hero-card">
      <h3 style="margin:0 0 8px 0;color:#fff">Session notes (what to expect)</h3>
      <ul style="color:var(--muted);margin-top:8px">
        <li>Begin with a short orientation and seating options.</li>
        <li>Sound layers are introduced and eased; volume stays conversational and low-frequency is limited upon request.</li>
        <li>Time to debrief and small takeaways after the sound segment.</li>
      </ul>
    </section>

    <footer>
      <div>Questions? Call <strong>{{PHONE}}</strong> or email <strong>{{EMAIL}}</strong></div>
      <div style="margin-top:6px">Serving {{CITY}}, {{STATE}} — handcrafted small gatherings and careful support.</div>
    </footer>
  </main>

  <script>
    (function(){
      // Testimonials and rotating rotator
      const testimonials = [
        {text: "I leave quieter and a little more capable of tending to the day.", who: "— C.R., member", note: "Has attended 6 sessions"},
        {text: "Thoughtful pacing — felt safe and held the whole time.", who: "— J.P.", note: "Private session"},
        {text: "Calm without drowsiness; I slept better the night of the session.", who: "— M.S.", note: "Series pack"}
      ];
      const rotator = document.getElementById('rotator');
      let idx = 0;
      function render(){
        rotator.innerHTML = '';
        testimonials.forEach((t,i)=>{
          const el = document.createElement('div');
          el.className = 'testimonial';
          el.style.opacity = (i===idx)?'1':'0';
          el.style.transform = (i===idx)?'translateY(0)':'translateY(8px)';
          el.innerHTML = '<p>'+t.text+'</p><div class="meta"><div style="font-size:13px;color:var(--muted)">'+t.who+'</div><div style="font-size:12px;color:#9ed6ff;margin-left:auto">'+t.note+'</div></div>';
          rotator.appendChild(el);
        });
      }
      render();
      setInterval(()=>{ idx = (idx + 1) % testimonials.length; render(); },5000);

      // Simple tooltip affordances for badges (improve accessibility)
      document.querySelectorAll('.badge').forEach(b=>{
        b.addEventListener('mouseenter',e=>{
          const tip = b.nextElementSibling; tip.style.opacity = 1; tip.style.transform = 'translateY(0)';
        });
        b.addEventListener('mouseleave',e=>{
          const tip = b.nextElementSibling; tip.style.opacity = 0; tip.style.transform = 'translateY(-6px)';
        });
        b.addEventListener('focus',e=>{ const tip = b.nextElementSibling; tip.style.opacity = 1; });
        b.addEventListener('blur',e=>{ const tip = b.nextElementSibling; tip.style.opacity = 0; });
      });
    })()
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#071226;--muted:#9fb3bf;--accent:#70c9ff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;background:linear-gradient(180deg,#06101a 0%,#081826 100%),url('assets/img/pattern.svg');color:#eaf6ff}
    header{display:flex;justify-content:space-between;padding:16px 22px;background:rgba(255,255,255,0.02)}
    .logo{width:42px;height:42px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#63d7b8);display:flex;align-items:center;justify-content:center;font-weight:700;color:#012426}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none}
    .wrap{max-width:960px;margin:26px auto;padding:20px}
    h1{margin:0 0 14px 0}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px}
    .faqs{background:rgba(255,255,255,0.02);padding:18px;border-radius:10px}
    .faq{border-bottom:1px solid rgba(255,255,255,0.02);padding:12px 0}
    .q{display:flex;justify-content:space-between;align-items:center;cursor:pointer}
    .a{margin-top:8px;color:var(--muted);display:none}
    .open .a{display:block}
    .comparator{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:10px}
    .toggle{display:flex;background:#0b1620;border-radius:8px;padding:6px;width:260px}
    .toggle button{flex:1;padding:8px;border:0;background:transparent;color:var(--muted);cursor:pointer;border-radius:6px}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),#63d7b8);color:#012426}
    .price{font-weight:700;font-size:22px;margin-top:12px}
    footer{margin-top:26px;color:var(--muted);font-size:14px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700;color:#dff6ff">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Questions people ask before coming</h1>
    <div class="grid">
      <div class="faqs">
        <div class="faq open">
          <div class="q" tabindex="0"><div><strong>What should I bring?</strong></div><div style="color:var(--muted)">+</div></div>
          <div class="a">Comfortable clothes, an intention, and anything that helps with lying or sitting (mat, pillow). We provide some mats and blankets but bring favorites for full comfort.</div>
        </div>

        <div class="faq">
          <div class="q" tabindex="0"><div><strong>How loud are the sessions?</strong></div><div style="color:var(--muted)">+</div></div>
          <div class="a">Volume is moderated to remain supportive rather than overwhelming. We also offer a low-volume lane; contact us if you are sound-sensitive.</div>
        </div>

        <div class="faq">
          <div class="q" tabindex="0"><div><strong>Can I attend if I have health concerns?</strong></div><div style="color:var(--muted)">+</div></div>
          <div class="a">If you have epilepsy, a pacemaker, are pregnant, or have other medical concerns, please consult your provider and contact us. Private formats can be adapted.</div>
        </div>

        <div class="faq">
          <div class="q" tabindex="0"><div><strong>Do I need to meditate already?</strong></div><div style="color:var(--muted)">+</div></div>
          <div class="a">No. Sessions are accessible to newcomers and those with experience. Guidance is given throughout, and you can participate however feels right.</div>
        </div>
      </div>

      <aside>
        <div class="comparator">
          <div style="font-weight:700;color:#dff6ff">Compare: membership vs series</div>
          <div style="margin-top:10px">Toggle to see effective per-session costs</div>
          <div class="toggle" role="tablist" style="margin-top:12px">
            <button id="opt-monthly" class="active">Monthly</button>
            <button id="opt-pack">4-Session Pack</button>
          </div>
          <div class="price" id="price">$0</div>
          <div style="font-size:13px;color:var(--muted);margin-top:8px">Annual savings and member perks change booking priority and per-session cost.</div>
          <a href="{{PRIMARY_CTA_URL}}" style="display:inline-block;margin-top:12px;padding:10px 14px;background:linear-gradient(90deg,var(--accent),#63d7b8);color:#012426;border-radius:8px;text-decoration:none;font-weight:600">Join or Reserve</a>
        </div>
      </aside>
    </div>

    <footer>
      <div>Need to talk before booking? Call <strong>{{PHONE}}</strong> or email <strong>{{EMAIL}}</strong></div>
    </footer>
  </main>

  <script>
    // FAQ toggle
    document.querySelectorAll('.faq .q').forEach(q=>{
      q.addEventListener('click',()=>q.parentElement.classList.toggle('open'));
      q.addEventListener('keypress',e=>{ if(e.key === 'Enter' || e.key === ' ') q.parentElement.classList.toggle('open'); });
    });

    // Pricing comparator micro
    const monthlyBtn = document.getElementById('opt-monthly');
    const packBtn = document.getElementById('opt-pack');
    const priceEl = document.getElementById('price');
    const values = {
      monthly: {label:'Monthly Membership', value:38},
      pack: {label:'4-Session Pack', value:44}
    };
    let current = 'monthly';

    function animateNumber(from,to,duration=600){
      const start = performance.now();
      function frame(ts){
        const t = Math.min(1,(ts-start)/duration);
        const val = Math.round(from + (to-from)*t);
        priceEl.textContent = '$'+val.toString();
        if(t<1) requestAnimationFrame(frame);
      }
      requestAnimationFrame(frame);
    }

    function setMode(mode){
      if(mode===current) return;
      const from = values[current].value;
      const to = values[mode].value;
      current = mode;
      monthlyBtn.classList.toggle('active', mode==='monthly');
      packBtn.classList.toggle('active', mode==='pack');
      animateNumber(from,to);
    }
    // init
    priceEl.textContent = '$'+values.monthly.value;
    monthlyBtn.addEventListener('click',()=>setMode('monthly'));
    packBtn.addEventListener('click',()=>setMode('pack'));
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#04131a;--muted:#9db8c4;--accent:#7dd3ff}
    body{margin:0;font-family:Inter,system-ui,Segoe UI,Roboto,Arial;color:#e9fbff;background:linear-gradient(180deg,#02101a,#071826),url('assets/img/pattern.svg')}
    header{display:flex;justify-content:space-between;align-items:center;padding:14px 20px;background:rgba(255,255,255,0.02)}
    .logo{width:40px;height:40px;border-radius:8px;background:linear-gradient(135deg,var(--accent),#62d9b1);display:flex;align-items:center;justify-content:center;font-weight:700;color:#002026}
    nav a{color:var(--muted);margin-left:12px;text-decoration:none}
    .wrap{max-width:980px;margin:26px auto;padding:18px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:18px}
    .card{background:rgba(255,255,255,0.02);padding:18px;border-radius:10px}
    form label{display:block;margin-top:10px;font-size:13px}
    input,select,textarea{width:100%;padding:10px;margin-top:6px;border-radius:8px;border:0;background:#06121a;color:#eaf6ff}
    .submit{margin-top:14px;padding:12px 16px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#63d7b8);color:#002026;border:0;cursor:pointer;font-weight:700}
    .opts{display:flex;gap:12px;margin-top:12px}
    .option{flex:1;padding:12px;border-radius:8px;background:rgba(255,255,255,0.01);cursor:pointer;text-align:center}
    .option.active{background:linear-gradient(90deg,var(--accent),#63d7b8);color:#022426}
    .pricebox{margin-top:12px;padding:12px;border-radius:8px;background:rgba(255,255,255,0.015);font-weight:700}
    .disclaimer{margin-top:12px;font-size:13px;color:#ffd8d8;padding:10px;border-radius:8px;background:linear-gradient(90deg,rgba(255,0,0,0.02),transparent)}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:10px">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700;color:#dff6ff">Reserve a spot</div>
        <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
      </div>
    </div>
    <nav>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private Care</a>
      <a href="about.html">About</a>
      <a href="faq.html">Help</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="card">
        <h2 style="margin:0 0 8px 0">Reserve</h2>
        <p style="color:var(--muted);margin:0 0 12px 0">Choose the session type and let us know any accommodations. We'll follow up to confirm availability.</p>

        <form id="booking" onsubmit="return false">
          <label for="name">Full name</label>
          <input id="name" name="name" required />

          <label for="email">Email</label>
          <input id="email" name="email" type="email" required />

          <label for="phone">Phone</label>
          <input id="phone" name="phone" />

          <label for="service">Service</label>
          <div class="opts" role="tablist">
            <div class="option active" data-service="gathering">Group Evening</div>
            <div class="option" data-service="private">Private Session</div>
            <div class="option" data-service="member">Membership</div>
          </div>

          <div class="pricebox">
            <div style="font-size:13px;color:var(--muted)">Per-person rate</div>
            <div style="font-size:28px;margin-top:6px" id="bookingPrice">$0</div>
            <div style="font-size:12px;color:var(--muted);margin-top:6px" id="priceNote">—</div>
          </div>

          <label for="notes">Notes (medical info, accessibility)</label>
          <textarea id="notes" name="notes" rows="3"></textarea>

          <div class="disclaimer">If you have epilepsy, a pacemaker, are pregnant, or have other concerns, please consult your health provider before booking. We can adapt private sessions on request.</div>

          <button class="submit" id="submitBtn">Confirm & Request</button>
        </form>
      </section>

      <aside class="card">
        <div style="font-weight:700;color:#dff6ff">Quick compare: Monthly vs Pack</div>
        <div style="color:var(--muted);margin-top:8px">Switch the toggle to see effective per-session pricing and member perks.</div>
        <div style="display:flex;gap:8px;margin-top:12px">
          <button id="cmpMonthly" style="flex:1;padding:10px;border-radius:8px;border:0;background:linear-gradient(90deg,var(--accent),#63d7b8);color:#012426;cursor:pointer">Monthly</button>
          <button id="cmpPack" style="flex:1;padding:10px;border-radius:8px;border:0;background:rgba(255,255,255,0.01);color:var(--muted);cursor:pointer">4-Pack</button>
        </div>

        <div style="margin-top:12px;font-size:13px;color:var(--muted)">Per-session</div>
        <div style="font-size:32px;font-weight:800;margin-top:6px" id="cmpPrice">$0</div>
        <div style="margin-top:8px;color:var(--muted)" id="cmpLine">—</div>

        <a href="{{PRIMARY_CTA_URL}}" style="display:inline-block;margin-top:14px;padding:10px 14px;background:linear-gradient(90deg,var(--accent),#63d7b8);color:#022426;border-radius:8px;text-decoration:none;font-weight:700">Proceed to {{PRIMARY_CTA_LABEL}}</a>
      </aside>
    </div>

    <footer style="margin-top:18px;color:var(--muted)">Questions before booking? Reach out: <strong>{{PHONE}}</strong> • <a href="mailto:{{EMAIL}}" style="color:inherit">{{EMAIL}}</a></footer>
  </main>

  <script>
    // Booking options behavior
    (function(){
      const options = document.querySelectorAll('.option');
      const priceEl = document.getElementById('bookingPrice');
      const noteEl = document.getElementById('priceNote');
      const submitBtn = document.getElementById('submitBtn');

      const rates = {
        gathering: {price:20,note:'Typical community event — sliding scale available.'},
        private: {price:120,note:'Private session — adjusted per time/needs.'},
        member: {price:12,note:'Member effective per-session cost (with ongoing access).'}
      };

      function setActive(service){
        options.forEach(o=>o.classList.toggle('active', o.dataset.service===service));
        const r = rates[service];
        animateNumber(parseInt(priceEl.textContent.replace(/[^0-9]/g,''))||0, r.price);
        noteEl.textContent = r.note;
      }

      options.forEach(o=>o.addEventListener('click',()=>setActive(o.dataset.service)));
      // init
      setActive('gathering');

      // simple animate helper
      function animateNumber(from,to,duration=500){
        const start = performance.now();
        function frame(now){
          const t = Math.min(1,(now-start)/duration);
          const val = Math.round(from + (to-from)*t);
          priceEl.textContent = '$'+val;
          if(t<1) requestAnimationFrame(frame);
        }
        requestAnimationFrame(frame);
      }

      // Submit handler: open a mailto as a lightweight placeholder
      document.getElementById('booking').addEventListener('submit',function(e){
        e.preventDefault();
        const name = document.getElementById('name').value || 'Guest';
        const email = document.getElementById('email').value || '{{EMAIL}}';
        const phone = document.getElementById('phone').value || '';
        const notes = document.getElementById('notes').value || '';
        const selected = document.querySelector('.option.active').dataset.service;
        const subject = encodeURIComponent('Booking request: '+selected+' — '+name);
        const body = encodeURIComponent('Name: '+name+'\nEmail: '+email+'\nPhone: '+phone+'\nService: '+selected+'\nNotes: '+notes);
        window.location.href = 'mailto:{{EMAIL}}?subject='+subject+'&body='+body;
      });
    })();

    // Comparator aside
    (function(){
      const monthly = {label:'Monthly', value:12}; // per-session effective
      const pack = {label:'4-Pack', value:18};
      const btnMonthly = document.getElementById('cmpMonthly');
      const btnPack = document.getElementById('cmpPack');
      const priceEl = document.getElementById('cmpPrice');
      const line = document.getElementById('cmpLine');

      function animate(from,to){
        const start = performance.now();
        function frame(now){
          const t = Math.min(1,(now-start)/600);
          const val = Math.round(from + (to-from)*t);
          priceEl.textContent = '$'+val; if(t<1) requestAnimationFrame(frame);
        }
        requestAnimationFrame(frame);
      }
      btnMonthly.addEventListener('click',()=>{
        btnMonthly.style.background = 'linear-gradient(90deg,#7dd3ff,#63d7b8)'; btnMonthly.style.color='#012426';
        btnPack.style.background='rgba(255,255,255,0.01)'; btnPack.style.color='var(--muted)';
        animate(parseInt(priceEl.textContent.replace(/[^0-9]/g,''))||0, monthly.value);
        line.textContent = 'Includes booking priority and community credits.';
      });
      btnPack.addEventListener('click',()=>{
        btnPack.style.background = 'linear-gradient(90deg,#7dd3ff,#63d7b8)'; btnPack.style.color='#012426';
        btnMonthly.style.background='rgba(255,255,255,0.01)'; btnMonthly.style.color='var(--muted)';
        animate(parseInt(priceEl.textContent.replace(/[^0-9]/g,''))||0, pack.value);
        line.textContent = 'One-off pack, no recurring commitment.';
      });
      // init monthly
      btnMonthly.click();
    })();
  </script>
</body>
</html>"} 
